def degree_centrality(edges, nodes):
    N = len(nodes)
    deg = {n: 0 for n in nodes}
    for n, outs in edges.items():
        deg[n] += len(outs)
        for o in outs:
            deg[o] = deg.get(o, 0) + 1
    return {n: round(d / (N - 1), 4) if N > 1 else 0.0 for n, d in deg.items()}

