import numpy as np

def lof_ratio(point, neighbors, all_points, k=3):
    def k_dist(p):
        d = np.sort(np.linalg.norm(all_points - p, axis=1))
        return d[min(k, len(d)-1)]
    own = k_dist(point)
    if own == 0:
        return 1.0
    avg_neighbor = np.mean([k_dist(nb) for nb in neighbors])
    return round(float(avg_neighbor / own), 4)

