import numpy as np

def reservoir_sample(stream, k, seed=0):
    rng = np.random.default_rng(seed)
    reservoir = []
    for i, x in enumerate(stream):
        if i < k:
            reservoir.append(x)
        else:
            j = rng.integers(0, i + 1)
            if j < k:
                reservoir[j] = x
    return reservoir
